import sys, zipfile
import xml.etree.ElementTree as ET

path = sys.argv[1] if len(sys.argv) > 1 else 'budget.xlsx'

def local(tag):
    return tag.split('}')[-1]

def children(elem, name):
    return [c for c in elem if local(c.tag) == name]

def attr_local(elem, name):
    for k, v in elem.attrib.items():
        if local(k) == name:
            return v
    return None

R_NS = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

with zipfile.ZipFile(path) as z:
    names = set(z.namelist())

    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in children(root, 'si'):
            text = ''.join(n.text or '' for n in si.iter() if local(n.tag) == 't')
            shared.append(text)

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in children(wb_root, 'sheets'):
        for s in children(sh, 'sheet'):
            sheets.append((attr_local(s, 'name'), attr_local(s, 'id')))

    rels = {}
    rel_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    for rel in children(rel_root, 'Relationship'):
        rels[attr_local(rel, 'Id')] = attr_local(rel, 'Target')

    print("Sheets:", [name for name, _ in sheets])
    grand = 0.0
    for name, rid in sheets:
        target = rels.get(rid, '')
        sheet_path = target if target.startswith('/') else 'xl/' + target
        sheet_path = sheet_path.lstrip('/')
        print(f"\n=== Sheet: {name} ({sheet_path}) ===")
        ws_root = ET.fromstring(z.read(sheet_path))
        sheet_sum = 0.0
        for sd in children(ws_root, 'sheetData'):
            for row in children(sd, 'row'):
                cells = []
                for c in children(row, 'c'):
                    ref = attr_local(c, 'r') or ''
                    t = attr_local(c, 't')
                    vnodes = children(c, 'v')
                    val = None
                    if t == 's':
                        val = shared[int(vnodes[0].text)] if vnodes else None
                    elif t == 'inlineStr':
                        is_el = children(c, 'is')
                        val = ''.join(n.text or '' for n in is_el[0].iter() if local(n.tag) == 't') if is_el else None
                    elif t == 'b':
                        val = (vnodes[0].text == '1') if vnodes else None
                    elif t == 'e':
                        val = '#' + (vnodes[0].text or '') if vnodes else None
                    else:
                        if vnodes:
                            txt = vnodes[0].text
                            try:
                                val = float(txt) if ('.' in txt or 'e' in txt.lower()) else int(txt)
                            except (TypeError, ValueError):
                                val = txt
                    if val is not None:
                        cells.append((ref, val))
                        if isinstance(val, (int, float)) and not isinstance(val, bool):
                            sheet_sum += val
                if cells:
                    print(cells)
        print(f"--- sum of numeric values in '{name}': {sheet_sum}")
        grand += sheet_sum
    print(f"\nGRAND TOTAL numeric sum across all sheets: {grand}")

